-- A.6 fix: add sister_company.type_changed to public.audit_action enum.\n--\n-- The sister-company type change trigger (migration 20261125000000) writes\n-- audit_logs with action 'sister_company.type_changed', but that value was\n-- not added to the public.audit_action enum. Without this value the trigger\n-- fails with:\n--\n--   invalid input value for enum audit_action: \"sister_company.type_changed\"\n--\n-- This migration adds the missing enum value so existing and new environments\n-- can apply migration 20261125000000 without error.\n\nalter type public.audit_action\n  add value if not exists 'sister_company.type_changed';\n\ncomment on type public.audit_action is\n  'Audit action vocabulary extended with sister_company.type_changed (A.6).';\n\n-- ---------------------------------------------------------------------------\n-- Verification\n-- ---------------------------------------------------------------------------\ndo $verify_sister_company_type_audit_action$\ndeclare\n  v_count integer;\nbegin\n  select count(*) into v_count\n    from pg_enum\n   where enumtypid = 'public.audit_action'::regtype\n     and enumlabel = 'sister_company.type_changed';\n\n  if v_count = 0 then\n    raise exception 'audit_action.sister_company.type_changed is missing';\n  end if;\nend\n$verify_sister_company_type_audit_action$;\n
